package v1

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"

	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

func reproClient(t *testing.T, calls *int32) *Client {
	t.Helper()
	policy := pipedrive.RetryPolicy{
		MaxAttempts:     4,
		BaseDelay:       time.Millisecond,
		MaxDelay:        time.Millisecond,
		RetryAllMethods: true,
	}
	return newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &policy}, func(w http.ResponseWriter, r *http.Request) {
		n := atomic.AddInt32(calls, 1)
		if n == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limit"}`))
			return
		}
		body, _ := io.ReadAll(r.Body)
		fmt.Printf("  attempt %d body len=%d TE=%v CL=%d\n", n, len(body), r.TransferEncoding, r.ContentLength)
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})
}

func multipartBuffer(t *testing.T, f io.Reader) (io.Reader, string) {
	var buf bytes.Buffer
	w := multipart.NewWriter(&buf)
	part, err := w.CreateFormFile("file", "doc.txt")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := io.Copy(part, f); err != nil {
		t.Fatal(err)
	}
	if err := w.Close(); err != nil {
		t.Fatal(err)
	}
	return &buf, w.FormDataContentType()
}

func multipartPipe(f io.Reader) (io.Reader, string) {
	pr, pw := io.Pipe()
	w := multipart.NewWriter(pw)
	go func() {
		part, err := w.CreateFormFile("file", "doc.txt")
		if err != nil {
			_ = pw.CloseWithError(err)
			return
		}
		if _, err := io.Copy(part, f); err != nil {
			_ = pw.CloseWithError(err)
			return
		}
		_ = pw.CloseWithError(w.Close())
	}()
	return pr, w.FormDataContentType()
}

func TestReproUploadRetry(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "doc.txt")
	if err := os.WriteFile(path, []byte("hello world contents"), 0o600); err != nil {
		t.Fatal(err)
	}

	cases := []struct {
		name string
		make func(t *testing.T) (io.Reader, string)
	}{
		{"bytes.Buffer multipart", func(t *testing.T) (io.Reader, string) {
			f, _ := os.Open(path)
			t.Cleanup(func() { f.Close() })
			return multipartBuffer(t, f)
		}},
		{"io.Pipe streaming multipart", func(t *testing.T) (io.Reader, string) {
			f, _ := os.Open(path)
			t.Cleanup(func() { f.Close() })
			return multipartPipe(f)
		}},
		{"raw *os.File", func(t *testing.T) (io.Reader, string) {
			f, _ := os.Open(path)
			t.Cleanup(func() { f.Close() })
			return f, "application/octet-stream"
		}},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var calls int32
			client := reproClient(t, &calls)
			body, ct := tc.make(t)
			_, err := client.Files.Add(context.Background(), body, ct)
			fmt.Printf("%-32s calls=%d err=%v\n", tc.name, atomic.LoadInt32(&calls), err)
		})
	}
}
EOF
