// file part plus the supplied form fields. Fields are written before the file
// part, in sorted key order, so the encoding is deterministic.
//
// The returned body has the same replay guarantees as NewFile.
func NewFileWithFields(fieldName, fileName string, src io.Reader, fields url.Values) (string, *bytes.Reader, error) {
