package v1

import (
	"context"
	"errors"
	"io"
	"mime"
	"mime/multipart"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

type uploadAttempt struct {
	values   url.Values
	fileName string
	content  string
}

type uploadRecorder struct {
	mu       sync.Mutex
	attempts []uploadAttempt
}

func (u *uploadRecorder) record(t *testing.T, r *http.Request) int {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil {
		t.Errorf("parse content type: %v", err)
		return 0
	}
	if mediaType != "multipart/form-data" {
		t.Errorf("unexpected media type: %q", mediaType)
		return 0
	}

	form, err := multipart.NewReader(r.Body, params["boundary"]).ReadForm(1 << 20)
	if err != nil {
		t.Errorf("read form: %v", err)
		return 0
	}
	defer func() { _ = form.RemoveAll() }()

	attempt := uploadAttempt{values: url.Values(form.Value)}
	if files := form.File["file"]; len(files) == 1 {
		attempt.fileName = files[0].Filename
		opened, err := files[0].Open()
		if err != nil {
			t.Errorf("open file part: %v", err)
			return 0
		}
		defer func() { _ = opened.Close() }()
		content, err := io.ReadAll(opened)
		if err != nil {
			t.Errorf("read file part: %v", err)
			return 0
		}
		attempt.content = string(content)
	}

	u.mu.Lock()
	defer u.mu.Unlock()
	u.attempts = append(u.attempts, attempt)
	return len(u.attempts)
}

func (u *uploadRecorder) snapshot() []uploadAttempt {
	u.mu.Lock()
	defer u.mu.Unlock()
	return append([]uploadAttempt(nil), u.attempts...)
}

func retryAllClient(t *testing.T, handler http.HandlerFunc) *Client {
	t.Helper()

	policy := pipedrive.RetryPolicy{
		MaxAttempts:     3,
		BaseDelay:       time.Millisecond,
		MaxDelay:        time.Millisecond,
		RetryAllMethods: true,
	}
	return newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &policy}, handler)
}

func TestFilesService_Upload(t *testing.T) {
	t.Parallel()

	var uploads uploadRecorder
	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Errorf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Errorf("unexpected path: %s", r.URL.Path)
		}
		uploads.record(t, r)

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"contract.pdf"}}`))
	})

	file, err := client.Files.Upload(
		context.Background(),
		"contract.pdf",
		strings.NewReader("pdf-bytes"),
		WithFileDealID(DealID(42)),
	)
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 || file.Name != "contract.pdf" {
		t.Fatalf("unexpected file: %#v", file)
	}

	attempts := uploads.snapshot()
	if len(attempts) != 1 {
		t.Fatalf("expected 1 attempt, got %d", len(attempts))
	}
	if attempts[0].fileName != "contract.pdf" {
		t.Fatalf("unexpected multipart file name: %q", attempts[0].fileName)
	}
	if attempts[0].content != "pdf-bytes" {
		t.Fatalf("unexpected multipart content: %q", attempts[0].content)
	}
	if got := attempts[0].values.Get("deal_id"); got != "42" {
		t.Fatalf("unexpected deal_id: %q", got)
	}
}

func TestFilesService_UploadAssociationFields(t *testing.T) {
	t.Parallel()

	var uploads uploadRecorder
	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		uploads.record(t, r)
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":1}}`))
	})

	extra := url.Values{}
	extra.Set("custom_field", "value")

	if _, err := client.Files.Upload(
		context.Background(),
		"doc.txt",
		strings.NewReader("x"),
		WithFileDealID(DealID(1)),
		WithFilePersonID(PersonID(2)),
		WithFileOrganizationID(OrganizationID(3)),
		WithFileProductID(ProductID(4)),
		WithFileActivityID(ActivityID(5)),
		WithFileProjectID(ProjectID(6)),
		WithFileLeadID(LeadID("adf21080-0e10-11eb-879b-05d71fb426ec")),
		WithFileFormValues(extra),
