	query          url.Values
	form           fileUploadFields
	requestOptions []pipedrive.RequestOption
}

// fileUploadFields holds the multipart form fields that associate an uploaded
// file with a Pipedrive record. They are only sent by Upload; the other
// methods ignore them.
type fileUploadFields struct {
	dealID     *DealID
	personID   *PersonID
	orgID      *OrganizationID
	productID  *ProductID
	activityID *ActivityID
	projectID  *ProjectID
	leadID     *LeadID
	extra      url.Values
}

func (f fileUploadFields) values() (url.Values, error) {
	values := mergeQueryValues(nil, f.extra)
	if values == nil {
		values = url.Values{}
	}

	if err := setFormID(values, "deal_id", f.dealID, "deal id"); err != nil {
		return nil, err
	}
	if err := setFormID(values, "person_id", f.personID, "person id"); err != nil {
		return nil, err
	}
	if err := setFormID(values, "org_id", f.orgID, "organization id"); err != nil {
		return nil, err
	}
	if err := setFormID(values, "product_id", f.productID, "product id"); err != nil {
		return nil, err
	}
	if err := setFormID(values, "activity_id", f.activityID, "activity id"); err != nil {
		return nil, err
	}
	if err := setFormID(values, "project_id", f.projectID, "project id"); err != nil {
		return nil, err
	}
	if f.leadID != nil {
		if _, err := parseUUID(string(*f.leadID), "lead id"); err != nil {
			return nil, err
		}
		values.Set("lead_id", string(*f.leadID))
	}
	return values, nil
}

func setFormID[T ~int64](values url.Values, key string, id *T, label string) error {
	if id == nil {
		return nil
	}
	if err := validateID(*id, label); err != nil {
		return err
	}
	values.Set(key, strconv.FormatInt(int64(*id), 10))
	return nil
}

